const p = JSON.parse($input.first().json.input || '{}');
if (!p.woo_product_id || !p.talla) return [{ json: { error: 'Faltan woo_product_id y talla' } }];
const auth = 'Basic ' + Buffer.from($env.WOO_CONSUMER_KEY + ':' + $env.WOO_CONSUMER_SECRET).toString('base64');
const hdrs = { Authorization: auth, 'Content-Type': 'application/json' };
const base = $env.WOO_BASE_URL + '/wp-json/wc/v3';
const prodUrl = p.woo_variation_id
  ? base + '/products/' + p.woo_product_id + '/variations/' + p.woo_variation_id
  : base + '/products/' + p.woo_product_id;
const prod = await $helpers.httpRequest({ method: 'GET', url: prodUrl, headers: hdrs });
if (prod.stock_status !== 'instock' || prod.stock_quantity <= 0) {
  return [{ json: { error: 'out_of_stock', mensaje: 'Lo siento, esa talla se agotó justo ahora. busco una alternativa?' } }];
}
const lineItem = { product_id: parseInt(p.woo_product_id), quantity: parseInt(p.cantidad) || 1 };
if (p.woo_variation_id) lineItem.variation_id = parseInt(p.woo_variation_id);
const nombre = (p.nombre || 'Cliente').trim();
const tel = p.telefono || '';
const orderData = {
  payment_method: $env.WOO_PAYMENT_METHOD || 'mercadopago',
  payment_method_title: 'Mercado Pago',
  status: 'pending',
  billing: { first_name: nombre.split(' ')[0], last_name: nombre.split(' ').slice(1).join(' '), email: 'whatsapp@savia-wear.com', phone: tel },
  line_items: [lineItem],
  meta_data: [{ key: '_savia_whatsapp', value: tel }, { key: '_savia_talla', value: p.talla }]
};
const pedido = await $helpers.httpRequest({ method: 'POST', url: base + '/orders', headers: hdrs, body: orderData });
const pago_url = pedido.payment_url || pedido.checkout_payment_url || '';
return [{ json: { ok: true, woo_order_id: pedido.id, producto_nombre: prod.name, talla: p.talla, precio_cop: prod.price, pago_url, mensaje: 'aqui tienes el link para ' + prod.name + ' talla ' + p.talla + ':' } }];

